import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        if not url or not isinstance(url, str):
            raise Exception("Invalid URL provided.")
        if not parameters or not isinstance(parameters, dict):
            raise Exception("Invalid parameters provided.")
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("Empty data received from API.")
        df = pd.DataFrame(data)
        if df.empty:
            raise Exception("No valid data to create DataFrame.")
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numerical columns available for correlation.")
        corr_matrix = numeric_df.corr()
        fig, ax = plt.subplots()
        sns.heatmap(corr_matrix, annot=True, fmt=".2f", cmap='coolwarm', ax=ax)
        ax.set_title("Correlation Heatmap")
        return df, ax
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON data: {e}")
    except Exception as e:
        raise Exception(f"Error: {e}")

